package com.medtrack.medicine.service;
import com.medtrack.medicine.dto.*; import com.medtrack.medicine.entity.*; import com.medtrack.medicine.repository.*; import com.medtrack.shared.exception.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class MedicineService { private final MedicineRepository medicines; private final MedicineCategoryRepository categories; public MedicineService(MedicineRepository m,MedicineCategoryRepository c){medicines=m;categories=c;} public MedicineResponse create(MedicineRequest r){if(medicines.existsBySku(r.sku()))throw new DomainException("DUPLICATE_MEDICINE_SKU","Medicine SKU already exists");MedicineCategory c=category(r.categoryId()); return MedicineResponse.of(medicines.save(new Medicine(r.sku(),r.genericName(),r.brandName(),c,r.dosageForm(),r.strength(),r.unitOfMeasure(),r.storageTemp(),n(r.minStockThreshold()),shelf(r.minReceivingShelfLifeDays()),r.description())));} @Transactional(readOnly=true) public Page<MedicineResponse> list(String q,Pageable p){return (q==null||q.isBlank()?medicines.findAll(p):medicines.search(q,p)).map(MedicineResponse::of);} @Transactional(readOnly=true) public MedicineResponse get(UUID id){return MedicineResponse.of(find(id));} public MedicineResponse update(UUID id,MedicineRequest r){Medicine m=find(id);m.update(r.genericName(),r.brandName(),category(r.categoryId()),r.dosageForm(),r.strength(),r.unitOfMeasure(),r.storageTemp(),n(r.minStockThreshold()),shelf(r.minReceivingShelfLifeDays()),r.status()==null?m.getStatus():MedicineStatus.valueOf(r.status()),r.description());return MedicineResponse.of(m);} private Medicine find(UUID id){return medicines.findById(id).orElseThrow(()->new NotFoundException("Medicine"));} private MedicineCategory category(UUID id){return categories.findById(id).orElseThrow(()->new NotFoundException("Medicine category"));} private int n(Integer n){return n==null?0:n;} private int shelf(Integer n){return n==null?90:n;} }
